    s=json.loads((PUBLIC/'summary.json').read_text());p=json.loads((SRC/'protocol.json').read_text());partition=json.loads((ROOT/p['archive_partition']).read_text());rows={(r['true_candidate'],r['method']):r for r in s['results']};active=[r for r in s['results'] if r['method']=='active'];control=[r for r in s['results'] if r['method']=='random'];lines=[];add=lambda line='':lines.append(line)
